function warehouseLabel(value) {
  return {
    wh_hk_1: '香港仓',
    wh_sz_1: '深圳仓',
    wh_sg_1: '新加坡仓'
  }[value] || value || '';
}

function riskLabel(value) {
  return {
    high: '高风险',
    medium: '中风险',
    low: '低风险'
  }[value] || value || '';
}

function itemLine(entry) {
  const item = entry.item_id || entry.batch_key || '未知商品';
  const location = entry.location_code ? `库位${entry.location_code}` : '未知库位';
  const batch = entry.batch_no ? `批次${entry.batch_no}` : '未知批次';
  const risk = riskLabel(entry.risk_level) || entry.risk_level || '未知风险';
  return `${item}(${location}, ${batch}, ${risk}, ${entry.action || 'synced'})`;
}

return $input.all().map((item) => {
  const result = item.json;
  const syncedCount = Number(result.synced_count || 0);
  const details = Array.isArray(result.items)
    ? result.items.map((entry) => itemLine(entry)).join(', ')
    : '';
  const scope = [
    result.warehouse_id ? `仓库: ${warehouseLabel(result.warehouse_id)}` : '',
    result.category ? `分类: ${result.category}` : '',
    result.location_code ? `库位: ${result.location_code}` : '',
    result.expiry_risk ? `临期状态: ${result.expiry_risk}` : '',
    result.risk_level ? `风险: ${riskLabel(result.risk_level)}` : ''
  ].filter(Boolean).join('; ');
  const reply = result.ok
    ? `已同步${syncedCount}条库存批次快照到飞书表格。${scope ? '\n' + scope : ''}${details ? '\n明细: ' + details : ''}`
    : `同步库存批次快照失败：${result.error || 'unknown_error'} ${result.message || ''}`.trim();

  return {
    json: {
      ok: Boolean(result.ok),
      platform: source.platform,
      chat_id: source.chat_id,
      sender_id: source.sender_id,
      message_id: source.message_id,
      reply,
      tool_trace: [
        { tool: 'warehouse_inventory_table_sync_fast_path', input: route, output: result }
      ],
      raw_agent_output: result
    }
  };
});

